عميل: السلام عليكم بغيت موعد تلميع السبت بالليل
[أداة] search_services({"query": "تلميع"})
[نتيجة] {"services": [{"id": "polish", "name": "تلميع", "price_sar": 240, "duration_min": 120}]}
[أداة] get_available_slots({"service_id": "polish", "date": "2027-04-17"})
[نتيجة] {"date": "2027-04-17", "slots": ["08:00", "09:00", "09:30", "10:00", "10:30", "13:00"]}
[أداة] get_available_slots({"service_id": "polish", "date": "2027-04-17", "after": "18:00"})
